use glam::DVec3;use ingetrazo_core::{mesh::Mesh,heal::orient_faces};use serde_json::{Value,json};
fn main(){let args:Vec<_>=std::env::args().collect();let cases:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let mut results=vec![];for case in cases.as_array().unwrap(){let mut mesh=Mesh::new();for face in case["faces"].as_array().unwrap(){let points:Vec<usize>=face.as_array().unwrap().iter().map(|p|mesh.add_vertex(DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap()))).collect();mesh.add_face(points,vec![]).unwrap();}for(i,f)in mesh.faces.iter_mut().enumerate(){f.attrs.insert("source_index".into(),json!(i));}let out=orient_faces(&mesh).unwrap();let second=orient_faces(&out).unwrap();assert_eq!(out,second);results.push(json!({"faces":out.faces.iter().enumerate().map(|(i,f)|{assert_eq!(f.attrs["source_index"],json!(i));json!({"vertices":f.vertices.iter().map(|&v|out.vertices[v].position.to_array()).collect::<Vec<_>>(),"interior":f.interior})}).collect::<Vec<_>>()}));}std::fs::write(&args[2],serde_json::to_vec(&results).unwrap()).unwrap();}
